}

/* ---- Solution ---- */
.card {
  display: grid;
  align-content: space-between;
  box-sizing: border-box;
  width: 340px;
  aspect-ratio: 1.586;
  padding: 24px;
  border-radius: 16px;
  background-image:
    radial-gradient(circle at 100% 0, rgb(255 255 255 / 0.25), transparent 40%),
    radial-gradient(circle at 0 100%, rgb(236 72 153 / 0.5), transparent 50%),
    linear-gradient(135deg, #1e1b4b, #4338ca);
  box-shadow: 0 16px 32px rgb(67 56 202 / 0.35);
  color: #ffffff;
}

.chip {
  width: 44px;
  height: 32px;
  border: 1px solid rgb(0 0 0 / 0.2);
  border-radius: 6px;
  background-image: linear-gradient(135deg, #fde68a, #d97706);
}

.number {
  font-family: ui-monospace, Consolas, monospace;
  font-size: 20px;
  letter-spacing: 0.12em;
  word-spacing: 0.4em;
}

.card-footer {
  display: flex;
  align-items: flex-end;
  gap: 24px;
}

.holder,
.expiry {
  display: grid;
  gap: 2px;
}

.small {
  letter-spacing: 0.1em;
  text-transform: uppercase;
  opacity: 0.7;
}

.value {
  font-size: 14px;
  font-weight: 600;
}

.brand {
  display: flex;
  margin-left: auto;
  isolation: isolate;
}

.circle {
  width: 32px;
  height: 32px;
  border-radius: 50%;
}

.c2 {
  margin-left: -12px;
  mix-blend-mode: screen;
}
